    if (rtmFxApi && globalThis.Sequencer && typeof Sequence !== "undefined") {
        const rtmFxFiles = [
            "modules/lancer-weapon-fx/soundfx/TechWarn.ogg",
            "jb2a.zoning.inward.circle.once.bluegreen.01.01"
        ];
        await Sequencer.Preloader.preloadForClients(rtmFxFiles);
        await new Sequence()
            .sound()
                .file(rtmFxFiles[0])
                .volume(rtmFxApi.getEffectVolume(0.65))
            .effect()
                .file(rtmFxFiles[1])
                .atLocation(triggerData.targets?.[0]?.target ?? triggerData.triggeringToken ?? reactorToken)
                .scaleToObject(1.5)
                .filter("Glow", { color: 0x7e8cff })
                .play();
    }
}
catch (error) {
    console.warn("Road to Midnight automation FX skipped; mechanics continue normally.", error);
}

const target = triggerData.targets[0].target;

const heat = api.tierValue(
    reactorToken,
    [2, 3, 4]
);

const existingAbjures = api.findEffectsOnToken(
    target,
    "Abjure",
    {
        extraFlags: {
            abjureSourceId: reactorToken.id
        }
    }
);

for (const existingAbjure of existingAbjures) {
    await api.deleteEffect(
        target,
        existingAbjure
    );
}

await api.applyMark(
    reactorToken,
    [target],
    {
        effect: {
            name: "Abjure",
            icon: item.img,
            isCustom: true
        },

        note: `${heat} Heat each time this character makes an attack roll.`,

        duration: {
            label: "end",
            turns: 1,
            rounds: 0,
            overrideTurnOriginId: target.id
        },

        flagKey: "abjureSourceId",

        extraOptions: {
            abjureHeat: heat
        }
    }
);

reactions.evaluate:
const hit = triggerData.targets?.[0];

if (!hit?.target || !hit.crit)
    return false;

const targetUuid = hit.target.document.uuid;

const targetEntry = triggerData.flowState?.data?.acc_diff?.targets?.find(
    entry => entry.targetUuid === targetUuid
);

if (!targetEntry)
    return false;

return Number(targetEntry.cover ?? 0) === 0;

