}

const combat = game.combat;

if (!combat)
    return;

const turnKey = [
    combat.id,
    combat.round,
    combat.turn,
    combat.current?.tokenId
].join(":");

let state = api.getActorFlags(
    reactorToken.actor,
    "breakArmorState"
) || {};

if (state.turnKey !== turnKey) {
    state = {
        turnKey,
        hitTargets: {}
    };
}

const newlyShredded = [];

for (const result of triggerData.targets ?? []) {
    const target = result.target;

    if (!target)
        continue;

    if (api.hasStatus(target, "shredded"))
        continue;

    if (state.hitTargets[target.id]) {
        newlyShredded.push(target);
        continue;
    }

    state.hitTargets[target.id] = true;
}

await api.addActorFlags(
    reactorToken.actor,
    {
        breakArmorState: state
    }
);

if (!newlyShredded.length)
    return;

await api.applyEffectsToTokens({
    tokens: newlyShredded,
    effectNames: ["shredded"],
    note: "Break Armor"
});

try {
