}

const targets = await api.chooseToken(reactorToken, {
    count: 1,
    range: reactorToken.actor.system.sensor_range,
    includeSelf: true,
    filter: token =>
        api.isFriendly(reactorToken, token) &&
        !api.findEffectOnToken(token, "Dispersal Shield"),
    filterWarning: "Dispersal Shield must target the Priest or an allied character that is not already protected by Dispersal Shield.",
    soft: false,
    title: "DISPERSAL SHIELD",
    description: "Choose the Priest or an allied character within Sensors."
});

if (!targets?.length)
    return;

const target = targets[0];

const shieldValue = api.tierValue(
    reactorToken,
    [5, 6, 7]
);

const currentOvershield = Number(
    target.actor.system.overshield?.value ?? 0
);

const newOvershield = Math.max(
    currentOvershield,
    shieldValue
);

if (newOvershield !== currentOvershield) {
    await target.actor.update({
        "system.overshield.value": newOvershield
    });
}

const bonusId = "dispersal-shield-half-" + item.id + "-" + target.id;

await api.removeGlobalBonus(target.actor, bonus => bonus.context?.dispersalShield === true && bonus.context?.sourceItemId === item.id);
await api.removeConstantBonus(target.actor, bonus => bonus.context?.dispersalShield === true && bonus.context?.sourceItemId === item.id);

await api.addConstantBonus(target.actor, {
    id: bonusId,
    name: "Dispersal Shield",
    type: "target_modifier",
    subtype: "half_damage",
    rollTypes: ["damage"],
    applyToTargetter: true,
    context: {
        dispersalShield: true,
        sourceItemId: item.id,
        sourcePriestTokenId: reactorToken.id,
        protectedTokenId: target.id
    }
});

await api.applyEffectsToTokens(
    {
        tokens: [target],
        effectNames: [{ name: "Dispersal Shield", icon: item.img, isCustom: true }],
        note: "Dispersal Shield — next successful attack deals half damage",
        duration: { label: "indefinite" },
        notify: false
    },
    {
        dispersalShield: true,
        dispersalShieldSourceItemId: item.id,
        dispersalShieldBonusId: bonusId
    }
);

reactions.evaluate:
const target = triggerData.target;
if (!target?.actor) return false;
const effects = api.findEffectsOnToken(target, "Dispersal Shield", { extraFlags: { dispersalShieldSourceItemId: item.id } });
return effects.some(effect => {
    const bonusId = effect.flags?.["lancer-automations"]?.dispersalShieldBonusId;
    return !!bonusId
        && !!triggerData.flowState?.la_extraData?.bonusUsage?.candidates?.[bonusId]
        && api.getConstantBonuses(target.actor).some(bonus => bonus.id === bonusId);
});

