                .file(rtmFxFiles[0])
                .volume(rtmFxApi.getEffectVolume(0.65))
            .effect()
                .file(rtmFxFiles[1])
                .atLocation(triggerData.targets?.[0]?.target ?? triggerData.triggeringToken ?? reactorToken)
                .scaleToObject(1.6)
                .filter("Glow", { color: 0x35ffd2 })
                .play();
    }
}
catch (error) {
    console.warn("Road to Midnight automation FX skipped; mechanics continue normally.", error);
}

const target = triggerData.targets[0].target;

const choice = await api.startChoiceCard({
    mode: "or",
    title: "DRONE BARRAGE",
    icon: "fas fa-satellite-dish",
    description:
        `<b>${target.name}</b> is caught in the Hive's drone barrage.<br><br>` +
        `Choose one:<br>` +
        `<b>• Immobilized + Impaired</b> until the end of your next turn.<br>` +
        `<b>• Forced Movement</b> up to 4 spaces in a direction chosen by ${reactorToken.name}.`,
    item,
    originToken: reactorToken,
    relatedToken: target,
    userIdControl: api.getTokenOwnerUserId(target),
    choices: [
        {
            text: "Immobilized + Impaired",
            icon: "fas fa-lock"
        },
        {
            text: "Move Up To 4 Spaces",
            icon: "fas fa-arrows-alt"
        }
    ]
});

if (!choice)
    return;

if (choice.choiceIdx === 0) {
    await api.applyEffectsToTokens({
        tokens: [target],
        effectNames: [
            "immobilized",
            "impaired"
        ],
        note: "Drone Barrage",
        duration: {
            label: "end",
            turns: 1,
            rounds: 0,
            overrideTurnOriginId: target.id
        }
    });

    return;
}

if (choice.choiceIdx === 1) {
    await api.moveToken(target, {
        range: 4,
        free: true,
            title: "DRONE BARRAGE",
        description:
            `${reactorToken.name} moves ${target.name} up to 4 spaces. ` +
            `This is forced movement and does not provoke reactions.`
    });
}

const accDiff = triggerData.flowState?.data?.acc_diff;

if (!accDiff)
    return;

for (const targetData of accDiff.targets ?? []) {
    const finalTotal = Number(targetData.total ?? 0);

    if (finalTotal <= 0)
        continue;

    targetData.difficulty =
        Number(targetData.difficulty ?? 0) + finalTotal;
}

if (!(accDiff.targets?.length)) {
    const baseTotal = Number(accDiff.base?.total ?? 0);

    if (baseTotal > 0) {
        accDiff.base.difficulty =
            Number(accDiff.base.difficulty ?? 0) + baseTotal;
    }
}

reactions.evaluate:
if (triggerData.triggeringToken?.id !== reactorToken.id)
    return false;

if (triggerData.endActivation)
    return true;

return triggerData.item?.system?.lid === item?.system?.lid;

reactions.activationCode:
if (triggerType === "onActivation") {
    try {
        const rtmFxApi = game.modules.get("lancer-weapon-fx")?.api;
        if (rtmFxApi && globalThis.Sequencer && typeof Sequence !== "undefined") {
            const rtmFxFiles = [
                "modules/lancer-weapon-fx/soundfx/TechPrepare.ogg",
                "jb2a.zoning.inward.square.once.redyellow.01.01"
            ];
            await Sequencer.Preloader.preloadForClients(rtmFxFiles);
            await new Sequence()
                .sound()
                    .file(rtmFxFiles[0])
                    .volume(rtmFxApi.getEffectVolume(0.65))
                .effect()
                    .file(rtmFxFiles[1])
                    .atLocation(reactorToken)
                    .scaleToObject(1.8)
                    .filter("Glow", { color: 0xff3344 })
                    .play();
        }
    }
    catch (error) {
        console.warn("Road to Midnight automation FX skipped; mechanics continue normally.", error);
    }

}

const eyeOfMidnightSource = item.id;

const cleanupEyeOfMidnight = async () => {
    await api.removeEffectsByNameFromTokens({
        tokens: [reactorToken],
        effectNames: ["slow", "Eye of Midnight"],
        extraFlags: {
            eyeOfMidnightSource
        }
    });
};

if (triggerData.endActivation) {
    await cleanupEyeOfMidnight();
    return;
}

const alreadyActive = api.getActivatedItems(reactorToken)
    ?.some(activeItem => activeItem.id === item.id);

if (alreadyActive)
    return;

await api.applyEffectsToTokens(
    {
        tokens: [reactorToken],
        effectNames: [
            "slow",
            {
                name: "Eye of Midnight",
                icon: "worlds/Lancer/VTT stuff/virtual-marker.svg",
                isCustom: true
            }
        ],
        note: "Eye of Midnight"
    },
    {
        eyeOfMidnightSource
    }
);

await api.setItemAsActivated(
    item,
    reactorToken,
    "Quick",
    "Deactivate Eye of Midnight"
);

reactions.evaluate:
const mover = triggerData.triggeringToken ?? triggerData.token;

if (!mover)
    return false;

if (!api.getActivatedItems(reactorToken)?.some(i => i.id === item.id))
    return false;

if (!api.isHostile(reactorToken, mover))
    return false;

if (triggerData.moveInfo?.isTeleport)
    return false;

const threat = 3;

if (triggerType === "onMove") {
    const extra = triggerData.moveInfo?.extraData ?? {};

    return extra.eyeOfMidnightInterceptItemId === item.id
        && extra.eyeOfMidnightInterceptReactorId === reactorToken.id
        && extra.eyeOfMidnightInterceptMoverId === mover.id;
}

if (triggerType !== "onPreMove")
    return false;

const pendingIntercept = api.getActorFlags(
    reactorToken.actor,
    "eyeOfMidnightPendingIntercept"
);

if (
    triggerData.moveInfo?.isModified
    && pendingIntercept?.itemId === item.id
    && pendingIntercept?.moverId === mover.id
)
    return false;

const startDistance = api.getMinGridDistance(
    mover,
    reactorToken,
    triggerData.startPos
);

if (startDistance <= threat)
    return true;

const path = triggerData.moveInfo?.pathHexes ?? [];
const startIndex = Math.max(0, path.historyStartIndex ?? 0);

for (let i = startIndex; i < path.length; i++) {
    const step = path[i];

    const distance = api.getMinGridDistance(
        mover,
        reactorToken,
        { x: step.x, y: step.y }
