};

const tokenIsDestroyed = (token) => {
    if (!token?.actor)
        return true;

    return (token.actor.system.structure?.value ?? 1) <= 0
        || (token.actor.system.stress?.value ?? 1) <= 0;
};

const endFollowerCountBoost = async () => {
    const boostActive = api.getActorFlags(
        reactorToken.actor,
        "followerCountBoostActive"
    ) === true;

    if (!boostActive)
        return;

    const baseCap = Number(api.getActorFlags(
        reactorToken.actor,
        "followerCountBoostBaseCap"
    ));

    const startCost = Number(api.getActorFlags(
        reactorToken.actor,
        "followerCountBoostStartCost"
    ));

    if (Number.isFinite(baseCap) && Number.isFinite(startCost)) {
        const currentCost = Number(
            api.getIntentionalMoveData(reactorToken)?.cost ?? startCost
        );

        const boostCost = Math.max(0, currentCost - startCost);
        const desiredCap = baseCap + boostCost;
        const currentCap = Number(api.getMovementCap(reactorToken));

        if (Number.isFinite(currentCap) && currentCap !== desiredCap) {
            api.increaseMovementCap(
                reactorToken,
                desiredCap - currentCap
            );
        }
    }

    await api.removeActorFlags(reactorToken.actor, {
        followerCountBoostActive: true,
        followerCountBoostBaseCap: true,
        followerCountBoostStartCost: true
    });
};

const cleanupFollowerCount = async () => {
    await endFollowerCountBoost();

    const bonusId = api.getActorFlags(
        reactorToken.actor,
        "followerCountBonusId"
    );

    if (bonusId) {
        await api.removeGlobalBonus(
            reactorToken.actor,
